def minWindowWildcards(s, t):
    need = [0] * 26
    for ch in t:
        need[ord(ch) - 97] += 1
    cnt = [0] * 26
    deficit = len(t)
    q = 0
    left = 0
    best = -1
    for right, ch in enumerate(s):
        if ch == '?':
            q += 1
        else:
            c = ord(ch) - 97
            if cnt[c] < need[c]:
                deficit -= 1
            cnt[c] += 1
        while deficit <= q:
            length = right - left + 1
            if best < 0 or length < best:
                best = length
            out = s[left]
            if out == '?':
                q -= 1
            else:
                c = ord(out) - 97
                cnt[c] -= 1
                if cnt[c] < need[c]:
                    deficit += 1
            left += 1
    return best
